INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-am_1421-ee272', 'stk-am_1421', 'EE 272', 'doc', '{"docs": [{"id": "stk-dr-f98365", "n": "Dr. Abdullah Al-Garni", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "EE272 (لاب سيركيت 2) -- ترم 211\n\nالتحضير : بداية الكلاس يحضر\nطريقة الشرح : يشرح التجربة باختصار على السبورة\nالكويزات : سلخ وصراحة نظامها جدا سيء\nالمياجر: فيه اكسبريمنت تيست وكان متوسط بس تصحيحه شديد\nالفاينلات : فيه قسمين …الثيوريتيكال كان صعب جدا!! والتصحيح شديد كالعادة … الاكسبريمنتال كان متوسط بس الوقت ضيق جدا!!\nالقريد النهائي: طلعت معاه ب +B ولكن اقيمه ب +D\nالصوت: خافت وهادئ\nإضافات :\n1 - اللاب حسيته ثقيل معاه الصراحة\n2- توصيل المعلومة لك عليه\n3- اخلاقه عالية جدا ومحترم\n4- تصحيحه جدا شديد لدرجة انه رفع كل واحد مننا في النهاية 12 درجة !!!\n\nنصيحتي الاخيرة خليه اخراختياراتك واذا انحديت عليه نزل عنده بس بتتعب شوي.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1533428-ee272", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdullah-al-garni/98365/20", "user": "AM_1421", "ts": 1642012980000, "tid": 98365, "pn": 20}}]}', 1642012980000, 1794774614, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mzd-ee272', 'stk-mzd', 'EE 272', 'doc', '{"docs": [{"id": "stk-dr-f175782", "n": "Dr. Abdulaziz Al-Khulaifi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "T-212 EE272 (Lab)\n\nالتحضير : بداية المحاضرة ويحضر بالأسم، الدكتور مره شديد في التحضير.\n\nطريقة الشرح : اول شيء يبداء بشرح الكونسبت بشكل جدا ممتازة حتى لو ماكنت فاهمهم في اللكتشر. وبعدها يشرح فكرة التجربة واش راح نستخدم في التجربة بشكل جدا واضح.\n\nالكويزات : الكويزات صعبه الى متوسطة، لكن الوقت جدا قليل، وافرج الكويزات يكون غالبا فوق 5 من 10.\n\nالفاينلات : الجزء النظري كان متوسط ماهو مره صعب اذا كنت فاهم الاب و المادة(EE203)، اما بنسبة للجزء العملي فكان صعب مره 😦\nالقريد النهائي: A.\nالصوت: جدا واضح.\nإضافات :\n- الدكتور شديد جدا في تحضير و تصحيح وايضا الغش.\n- الدكتور اخلاقه ممتازة مشاء الله، والاب يكون ممتع معه.\n- بشكل عام الدكتور ممتاز وراح تطلع من كل لاب وانت متعلم معلومات جديدة.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1534480-ee272", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdulaziz-al-khulaifi/175782/5", "user": "MZD", "ts": 1653693815000, "tid": 175782, "pn": 5}}]}', 1653693815000, 1794774614, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
COMMIT;
